import React from 'react';

function Quiz({ question, onAnswer, currentQuestion, totalQuestions }) {
  return (
    <div className="bg-white shadow rounded-lg p-6">
      <div className="mb-4">
        <div className="text-sm text-gray-500 mb-2">
          คำถามที่ {currentQuestion + 1} จาก {totalQuestions}
        </div>
        <h2 className="text-xl font-semibold text-gray-900 mb-6">
          {question.text}
        </h2>
      </div>

      <div className="space-y-4">
        {question.options.map((option, index) => (
          <button
            key={index}
            onClick={() => onAnswer(option)}
            className="w-full text-left p-4 border rounded-lg hover:bg-gray-50 transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-opacity-50"
          >
            <div className="flex items-center">
              <div className="flex-1">
                <p className="text-gray-900">{option.text}</p>
                {option.description && (
                  <p className="text-sm text-gray-500 mt-1">{option.description}</p>
                )}
              </div>
            </div>
          </button>
        ))}
      </div>

      <div className="mt-8">
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div
            className="bg-primary h-2 rounded-full transition-all duration-300"
            style={{ width: `${((currentQuestion + 1) / totalQuestions) * 100}%` }}
          />
        </div>
      </div>
    </div>
  );
}

export default Quiz;
